/** Minimum zoom level where Rapid data is rendered */
const MINZOOM = 12;

/** Collected data from services, sorted by geometry type */
interface RapidData {
  points: OsmEntity[];
  vertices: Set<OsmEntity>;
  lines: OsmWay[];
  polygons: OsmEntity[];
}


